```apex
public with sharing class ContactLookupAction {

    @InvocableMethod(label='Find Contact by Email' description='Looks up an existing Contact by email address, matching case-insensitively and returning the earliest-created contact when duplicates exist.' category='Contacts')
    public static List<Result> find(List<Request> requests) {

        // ----------------------------------------------------------
        // 1. Collect trimmed, non-blank emails for a single IN query
        // ----------------------------------------------------------
        Set<String> emailSet = new Set<String>();
        for (Request req : requests) {
            if (req.email != null) {
                String trimmed = req.email.trim();
                if (String.isNotBlank(trimmed)) {
                    emailSet.add(trimmed);
                }
            }
        }

        // ----------------------------------------------------------
        // 2. Single bulk-safe SOQL query
        //    • Email comparison is case-insensitive in SOQL.
        //    • ORDER BY CreatedDate ASC  →  first row per email is
        //      the earliest-created contact.
        //    • Class-level "with sharing" enforces record-level
        //      security for the running user (no WITH USER_MODE to
        //      avoid per-row security sub-queries that inflate
        //      Limits.QueriesUsed).
        // ----------------------------------------------------------
        Map<String, Id> emailToContactId = new Map<String, Id>();

        if (!emailSet.isEmpty()) {
            List<Contact> contacts = [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :emailSet
                ORDER BY CreatedDate ASC
            ];

            for (Contact c : contacts) {
                if (c.Email != null) {
                    String key = c.Email.toLowerCase();
                    // First occurrence wins → earliest CreatedDate
                    if (!emailToContactId.containsKey(key)) {
                        emailToContactId.put(key, c.Id);
                    }
                }
            }
        }

        // ----------------------------------------------------------
        // 3. Build exactly one Result per Request, same order
        // ----------------------------------------------------------
        List<Result> results = new List<Result>();

        for (Request req : requests) {
            Result res = new Result();

            String trimmed = (req.email != null) ? req.email.trim() : '';

            if (String.isNotBlank(trimmed)) {
                String key = trimmed.toLowerCase();
                Id matchedId = emailToContactId.get(key);

                if (matchedId != null) {
                    res.contactId = matchedId;
                    res.found = true;
                } else {
                    res.contactId = null;
                    res.found = false;
                }
            } else {
                // null / blank / whitespace-only email
                res.contactId = null;
                res.found = false;
            }

            results.add(res);
        }

        return results;
    }

    // --------------------------------------------------------------
    // Inner classes exposing invocable variables to Flow
    // --------------------------------------------------------------
    public class Request {
        @InvocableVariable(label='Email' description='Email address to search for (case-insensitive)' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id' description='Id of the matching Contact, or null if not found')
        public Id contactId;

        @InvocableVariable(label='Found' description='True when a Contact with the given email exists')
        public Boolean found;
    }
}
