public class ErpAccountSyncJob implements Queueable {

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(QueueableContext context) {
        // Attach the finalizer BEFORE doing any work
        System.attachFinalizer(new ErpSyncFinalizer(this.accountIds, this.attempt));

        List<Account> accounts = [
            SELECT Id, Description
            FROM Account
            WHERE Id IN :this.accountIds
        ];

        for (Account a : accounts) {
            a.Description = 'Synced to ERP';
        }

        // Single DML is all-or-nothing.
        // Do NOT catch exceptions – let them propagate so the job fails
        // and none of the changes are persisted.
        update accounts;
    }
