```java
public class ErpSyncFinalizer implements Finalizer {

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(FinalizerContext context) {
        FinalizerContext.FinalizerResult result = context.getResult();
        Boolean jobSucceeded = (result == FinalizerContext.FinalizerResult.SUCCESS);

        FB_Job_Log__c log = new FB_Job_Log__c(
            Job_Name__c = 'ErpAccountSyncJob',
            Attempt__c  = this.attempt
        );

        if (jobSucceeded) {
            log.Status__c = 'Success';
        } else {
            log.Status__c = 'Failed';

            // Attempt to retrieve the actual error from AsyncApexJob
            String errorMessage = result != null ? result.name() : 'Job failed';
            String jobId = context.getAsyncApexJobId();
            if (jobId != null) {
                List<AsyncApexJob> jobs = [
                    SELECT ExtendedStatus
                    FROM AsyncApexJob
                    WHERE Id = :jobId
                    LIMIT 1
                ];
                if (!jobs.isEmpty() && String.isNotBlank(jobs[0].ExtendedStatus)) {
                    errorMessage = jobs[0].ExtendedStatus;
                }
            }

            // Truncate to 255 characters max
            log.Error__c = errorMessage.length() > 255
                ? errorMessage.substring(0, 255)
                : errorMessage;

            // Retry if fewer than 3 attempts
            if (this.attempt < 3) {
                System.enqueueJob(
                    new ErpAccountSyncJob(this.accountIds, this.attempt + 1)
                );
            }
        }

        insert log;
    }
}
