public with sharing class Opportunities extends fflib_SObjectDomain {

    public Opportunities(List<Opportunity> records) {
        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }

    private IOpportunityFulfilmentService fulfilmentService() {
        return (IOpportunityFulfilmentService)
            Application.Service.newInstance(IOpportunityFulfilmentService.class);
    }

    // Inserted directly as Closed Won -> fulfil (after insert so Ids are populated).
    public override void onAfterInsert() {
        Set<Id> qualifyingIds = new Set<Id>();
        for (Opportunity opp : (List<Opportunity>) records) {
            if (opp.StageName == 'Closed Won') {
                qualifyingIds.add(opp.Id);
            }
        }
        if (!qualifyingIds.isEmpty()) {
            fulfilmentService().startFulfilment(qualifyingIds);
        }
    }

    // Stage changed from anything other than Closed Won to Closed Won -> fulfil.
    public override void onBeforeUpdate() {
        Set<Id> qualifyingIds = new Set<Id>();
        for (Opportunity opp : (List<Opportunity>) records) {
            if (opp.StageName == 'Closed Won'
                    && Trigger.oldMap.get(opp.Id).StageName != 'Closed Won') {
                qualifyingIds.add(opp.Id);
            }
        }
        if (!qualifyingIds.isEmpty()) {
            fulfilmentService().startFulfilment(qualifyingIds);
        }
    }
}
