public with sharing class Accounts extends fflib_SObjects implements IAccounts {

    public Accounts(List<SObject> records) {
        super(records);
    }

    public static IAccounts newInstance(List<Account> records) {
        List<SObject> sObjRecords = new List<SObject>();
        sObjRecords.addAll(records);
        return (IAccounts) Application.Domain.newInstance(Account.SObjectType, sObjRecords);
    }

    public static IAccounts newInstance(Set<Id> accountIds) {
        List<SObject> sObjRecords = new List<SObject>();
        if (accountIds != null && !accountIds.isEmpty()) {
            fflib_SObjectSelector selector =
                (fflib_SObjectSelector) Application.Selector.newInstance(Account.SObjectType);
            sObjRecords = selector.selectSObjects(accountIds);
        }
        return (IAccounts) Application.Domain.newInstance(Account.SObjectType, sObjRecords);
    }

    public override SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public override Object getType() {
        return Account.SObjectType;
    }

    public List<Account> getAccounts() {
        List<Account> result = new List<Account>();
        for (SObject s : this.records) {
            result.add((Account) s);
        }
        return result;
    }

    public IAccounts selectByRating(String rating) {
        List<Account> filtered = new List<Account>();
        for (SObject s : this.records) {
            Account a = (Account) s;
            if (a.Rating == rating) {
                filtered.add(a);
            }
        }
        return Accounts.newInstance(filtered);
    }

    public Set<Id> getOwnerIds() {
        Set<Id> ownerIds = new Set<Id>();
        for (SObject s : this.records) {
            Account a = (Account) s;
            if (a.OwnerId != null) {
                ownerIds.add(a.OwnerId);
            }
        }
        return ownerIds;
    }

    public void setRating(String rating) {
        for (SObject s : this.records) {
            ((Account) s).Rating = rating;
        }
    }

    public class Constructor {
        public fflib_ISObjects newInstance(List<SObject> records) {
            return new Accounts(records);
        }
    }
}
