public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };

        // Track field API names (lower-cased) already present to avoid duplicates
        Set<String> addedFieldNames = new Set<String>();
        for (Schema.SObjectField f : fields) {
            addedFieldNames.add(f.getDescribe().getName().toLowerCase());
        }

        // Dynamically pull in every field the credit team's field set references
        Schema.FieldSet fs = Schema.SObjectType.Account.fieldSets.getMap().get('Credit_Review');
        if (fs != null) {
            Map<String, Schema.SObjectField> fieldMap =
                Schema.SObjectType.Account.fields.getMap();

            for (Schema.FieldSetMember fsm : fs.getDisplayedFields()) {
                String apiName = fsm.getFieldPath();
                // Relationship paths (e.g. "Account.Name") – keep only the leaf field
                if (apiName.contains('.')) {
                    apiName = apiName.substringAfterLast('.');
                }
                String lower = apiName.toLowerCase();
                if (!addedFieldNames.contains(lower) && fieldMap.containsKey(lower)) {
                    fields.add(fieldMap.get(lower));
                    addedFieldNames.add(lower);
                }
            }
        }

        return fields;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        List<String> fieldNames = new List<String>();
        for (Schema.SObjectField f : getSObjectFieldList()) {
            fieldNames.add(f.getDescribe().getName());
        }

        String soql = 'SELECT ' + String.join(fieldNames, ', ') +
                      ' FROM Account WITH USER_MODE WHERE Id IN :accountIds';

        return Database.query(soql);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        List<String> acctFieldNames = new List<String>();
        for (Schema.SObjectField f : getSObjectFieldList()) {
            acctFieldNames.add(f.getDescribe().getName());
        }

        // Delegate child-field selection to the existing ContactsSelector
        ContactsSelector contactsSelector = new ContactsSelector();
        List<String> contactFieldNames = new List<String>();
        for (Schema.SObjectField f : contactsSelector.getSObjectFieldList()) {
            contactFieldNames.add(f.getDescribe().getName());
        }

        String soql = 'SELECT ' + String.join(acctFieldNames, ', ') +
                      ', (SELECT ' + String.join(contactFieldNames, ', ') +
                      ' FROM Contacts) FROM Account WITH USER_MODE' +
                      ' WHERE Id IN :accountIds';

        return Database.query(soql);
    }
}
