/**
 * ErpCustomerSync
 *
 * Entry point  : push()   – called from AccountTrigger (trigger ctx).
 * Async gate   : sync()   – @Future(callout=true); runs in a separate
 *                           async context where HTTP callouts ARE permitted.
 * Worker       : doSync() – query → build JSON → POST; callable both
 *              :            from the future AND directly from tests.
 *
 * One POST per trigger batch.  Error handling / retries out of scope.
 */
public with sharing class ErpCustomerSync {

    // ---------------------------------------------------------------
    //  Trigger entry point (synchronous trigger context)
    // ---------------------------------------------------------------
    public static void push(List<Account> accounts) {

        if (accounts == null || accounts.isEmpty()) {
            return;
        }

        List<Id> ids = new List<Id>(accounts.size());
        for (Account a : accounts) {
            ids.add(a.Id);
        }

        // Hand off to an async context that is allowed to call out.
        sync(ids);
    }

    // ---------------------------------------------------------------
    //  Async gate – callout permission granted by callout=true
    // ---------------------------------------------------------------
    @Future(callout = true)
    public static void sync(List<Id> accountIds) {
        doSync(accountIds);
    }

    // ---------------------------------------------------------------
    //  Worker – runs inside the future (or can be called directly
    //  from a test method where synchronous callouts are allowed).
    // ---------------------------------------------------------------
    public static void doSync(List<Id> accountIds) {

        List<Account> accts = [
            SELECT Id, Name, BillingCountry
            FROM   Account
            WHERE  Id IN :accountIds
        ];

        if (accts.isEmpty()) {
            return;
        }

        // ---- build JSON array  [{"salesforceId":"…","name":"…","country":"…"},…] ----
        List<Map<String, Object>> payload = new List<Map<String, Object>>(accts.size());

        for (Account a : accts) {
            // BillingCountry → null when blank (ERP contract)
            String country = String.isBlank(a.BillingCountry)
                ? null
                : a.BillingCountry;

            payload.add(new Map<String, Object>{
                'salesforceId' => String.valueOf(a.Id),   // 18-char Id, no fragile cast
                'name'         => a.Name,
                'country'      => country                   // null → JSON null
            });
        }

        // ---- single POST to ERP via Named Credential ----
        HttpRequest req = new HttpRequest();
        req.setEndpoint('callout:ERP/api/customers');
        req.setMethod('POST');
        req.setHeader('Content-Type', 'application/json');
        req.setBody(JSON.serialize(payload));
        req.setTimeout(120000);

        Http http = new Http();
        http.send(req);   // 202 Accepted expected; error handling out of scope
    }
}
