/**
 * Publishes one Deal_Stage_Change__e platform event per Opportunity.
 *
 * DEVIATION NOTE: The task requests a per-record EventBus.publish() call inside
 * the loop. Salesforce's governor limit allows 30 EventBus.publish() calls per
 * transaction. Since this class can be invoked with up to 200 records from a
 * trigger handler, individual calls would exceed that limit. To satisfy both the
 * "one event per opportunity" requirement and the governor limit, all events are
 * assembled into a single list and published in ONE EventBus.publish() call.
 * The API returns a List<Database.SaveResult> with one result per event in the
 * same order, so per-record failure information is fully preserved.
 *
 * Compile fix: Id.toFormattedString() does not exist; use the implicit Id→String
 * conversion (opp.Id) which yields the 18-character case-safe representation.
 */
public with sharing class DealEventPublisher {

    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        if (opportunities == null || opportunities.isEmpty()) {
            return new List<Database.SaveResult>();
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>();

        for (Opportunity opp : opportunities) {
            Deal_Stage_Change__e evt = new Deal_Stage_Change__e();
            evt.Opportunity_Id__c = opp.Id;       // implicit 18-char string
            evt.Stage__c          = opp.StageName;
            evt.Amount__c         = opp.Amount;
            events.add(evt);
        }

        // Single bulk publish – 1 call instead of N, stays within the 30-call
        // EventBus.publish governor limit.  Results are ordered identically to
        // the input list, so the caller can correlate each SaveResult with the
        // original Opportunity.
        List<Database.SaveResult> results = EventBus.publish(events);

        return results;
    }
}
