```apex
/**
 * OpportunityTrigger
 *
 * After insert / after update (StageName or Amount changed):
 *   – collects every unique, non-null Account Id that needs recalculation,
 *   – hands them to ONE @future call so a 200-row CPQ batch never
 *     exceeds the 50-future-per-transaction governor limit.
 */
trigger OpportunityTrigger on Opportunity (after insert, after update) {

    // Avoid recursion when called from Batch / Future / Queueable.
    if (System.isBatch() || System.isFuture()) {
        return;
    }

    Set<Id> accountIds = new Set<Id>();

    if (Trigger.isInsert) {
        for (Opportunity opp : Trigger.new) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
    } else if (Trigger.isUpdate) {
        for (Integer i = 0; i < Trigger.new.size(); i++) {
            Opportunity newOpp = Trigger.new[i];
            Opportunity oldOpp = Trigger.old[i];

            // Recalculate only when StageName or Amount changed.
            if (newOpp.StageName == oldOpp.StageName &&
                newOpp.Amount      == oldOpp.Amount) {
                continue;
            }

            // New account (current owner of the opp).
            if (newOpp.AccountId != null) {
                accountIds.add(newOpp.AccountId);
            }

            // Old account (lost an opp – also needs recalculation).
            if (oldOpp.AccountId != null &&
                newOpp.AccountId != oldOpp.AccountId) {
                accountIds.add(oldOpp.AccountId);
            }
        }
    }

    if (!accountIds.isEmpty()) {
        AccountRatingService.recalculate(accountIds);
    }
}
