/**
 * AccountRatingService
 *
 * Determines Account.Rating from the account's OPEN opportunity pipeline:
 *   Hot  – at least one open opp with Amount >= 100000
 *   Warm – has open opps but none >= 100000
 *   Cold – no open opps
 *
 * Single @future with a Set<Id> parameter: a 200-record CPQ batch
 * collapses to ONE async call (deduplication handled by the Set).
 */
public with sharing class AccountRatingService {

    private static final Decimal HOT_THRESHOLD = 100000;

    /**
     * Recalculates Rating for every Account in the supplied set.
     * Safe to call directly in test context (e.g. between
     * Test.startTest / Test.stopTest) or via the trigger.
     */
    @future
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Remove any null keys that might have slipped in.
        if (accountIds.contains(null)) {
            accountIds.remove(null);
            if (accountIds.isEmpty()) {
                return;
            }
        }

        // ---- 1. Gather every OPEN opportunity for the affected accounts ----
        Set<Id>   accountsWithOpenOpps = new Set<Id>();
        Map<Id, Decimal> maxAmountByAccount = new Map<Id, Decimal>();

        for (Opportunity opp : [
            SELECT AccountId, Amount
            FROM   Opportunity
            WHERE  AccountId IN :accountIds
              AND  IsClosed  = false
              AND  IsWon     = false
        ]) {
            Id accId = opp.AccountId;
            accountsWithOpenOpps.add(accId);

            Decimal amt = (opp.Amount == null) ? 0 : opp.Amount;
            Decimal current = maxAmountByAccount.get(accId);
            if (current == null || amt > current) {
                maxAmountByAccount.put(accId, amt);
            }
        }

        // ---- 2. Build the update list (only if rating actually changes) ----
        List<Account> toUpdate = new List<Account>();

        for (Id accId : accountIds) {
            if (accId == null) {
                continue;
            }

            String newRating;

            if (!accountsWithOpenOpps.contains(accId)) {
                newRating = 'Cold';
            } else if (maxAmountByAccount.get(accId) >= HOT_THRESHOLD) {
                newRating = 'Hot';
            } else {
                newRating = 'Warm';
            }

            toUpdate.add(new Account(Id = accId, Rating = newRating));
        }

        // ---- 3. Bulk DML – never inside a loop ----
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
