/**
 * Sends a renewal-reminder email to each Opportunity's owner.
 *
 * Messages are batched into groups to stay within the 10-sendEmail-call
 * governor limit while still allowing per-email fault isolation
 * (allOrNone defaults to false).
 *
 * Designed to handle up to 200 opportunities per call (the job's chunk size).
 */
public with sharing class RenewalReminderService {

    // Number of messages per Messaging.sendEmail() call.
    // 200 records / 25 = 8 calls, safely under the 10-call limit.
    private static final Integer BATCH_SIZE = 25;

    /**
     * Sends one plain-text reminder email per Opportunity to its owner.
     *
     * @param opportunityIds  Ids of Opportunities whose renewal is due
     * @return number of emails that were accepted for delivery
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Bulk-safe: single query regardless of collection size.
        // Exclude owners that cannot receive email.
        List<Opportunity> opps = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM   Opportunity
            WHERE  Id       IN :opportunityIds
              AND  OwnerId  != null
              AND  Owner.IsActive = true
              AND  Owner.Email    != null
        ];

        if (opps.isEmpty()) {
            return 0;
        }

        // ---- Build all messages first (no DML / sendEmail inside this loop) ----
        List<Messaging.SingleEmailMessage> messages = new List<Messaging.SingleEmailMessage>();

        for (Opportunity opp : opps) {
            Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();

            // Internal-user delivery: does not consume external-email allocation.
            email.setTargetObjectId(opp.OwnerId);
            email.setSaveAsActivity(false);

            email.setSubject('Renewal due: ' + opp.Name);

            email.setPlainTextBody(
                'Hello,\n\n'
                + 'The renewal for "' + opp.Name + '" is due on '
                + opp.CloseDate.format() + '.\n\n'
                + 'Please take the necessary action before the close date.\n\n'
                + '— Renewal Reminder Service'
            );

            messages.add(email);
        }

        // ---- Send in batches to stay under the 10-call governor limit ----
        Integer sentCount = 0;

        for (Integer i = 0; i < messages.size(); i += BATCH_SIZE) {
            List<Messaging.SingleEmailMessage> batch =
                messages.getSubList(i, Math.min(i + BATCH_SIZE, messages.size()));

            try {
                Messaging.SendEmailResult[] results = Messaging.sendEmail(batch);

                for (Messaging.SendEmailResult result : results) {
                    if (result.isSuccess()) {
                        sentCount++;
                    } else {
                        // Log individual failures (e.g. inactive owner slipped through)
                        for (Messaging.SendEmailError err : result.getErrors()) {
                            System.debug(
                                LoggingLevel.WARN,
                                'RenewalReminderService: send failed – ' + err.getMessage()
                            );
                        }
                    }
                }
            } catch (Exception e) {
                // If an entire batch throws (e.g. all addresses invalid),
                // log and continue with the next batch.
                System.debug(
                    LoggingLevel.ERROR,
                    'RenewalReminderService: batch send error – ' + e.getMessage()
                );
            }
        }

        return sentCount;
    }
}
