import { LightningElement, wire } from 'lwc';
import {
    subscribe,
    unsubscribe,
    publish,
    APPLICATION_SCOPE,
    MessageContext
} from 'lightning/messageService';
import ACCOUNT_SELECTED from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    subscription = null;
    recordId = null;

    @wire(MessageContext)
    messageContext;

    /* ------------------------------------------------------------------ */
    /*  Lifecycle                                                         */
    /*  connectedCallback  -> subscribe (once per insertion)             */
    /*  disconnectedCallback -> unsubscribe & release                    */
    /* ------------------------------------------------------------------ */

    connectedCallback() {
        if (!this.subscription) {
            this.subscription = subscribe(
                ACCOUNT_SELECTED,
                this.messageContext,
                this.handleMessage,
                { scope: APPLICATION_SCOPE }
            );
        }
    }

    disconnectedCallback() {
        if (this.subscription) {
            unsubscribe(this.subscription, this.handleMessage);
            this.subscription = null;
        }
    }

    /* ------------------------------------------------------------------ */
    /*  Message listener                                                  */
    /*  Stable reference so unsubscribe can match the same function.     */
    /* ------------------------------------------------------------------ */

    handleMessage = (message) => {
        this.recordId = message ? message.recordId : null;
    };

    /* ------------------------------------------------------------------ */
    /*  Clear-selection button handler                                    */
    /* ------------------------------------------------------------------ */

    handleClearSelection() {
        publish(ACCOUNT_SELECTED, this.messageContext, { recordId: null });
    }
}
