                    );
                    this.dispatchEvent(
                        new ShowToastEvent({
                            title: 'Opportunity deleted',
                            variant: 'success'
                        })
                    );
                } catch (error) {
                    let message = 'Unknown error';
                    if (error && error.body && error.body.message) {
                        message = error.body.message;
                    }
                    this.dispatchEvent(
                        new ShowToastEvent({
                            title: 'Delete failed',
                            message: message,
                            variant: 'error'
                        })
                    );
                }
            }
        }
    }
}
