/**
 * Creates Enhanced Recurring Donations in NPSP from gift-form sign-ups.
 *
 * One call ⇒ one DML (insert of all Recurring_Donation__c records) and zero SOQL.
 * All validation is performed before any DML so a single bad request
 * rolls the entire batch back via the thrown exception.
 */
public with sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id       contactId;
        public Decimal  amount;
        public Integer  dayOfMonth;      // 1-31
        public Date     startDate;
        public Integer  installments;    // null / 0 ⇒ open-ended
        public String   paymentMethod;   // 'Credit Card', 'ACH', 'Check'
    }

    /**
     * @param requests  list of gift sign-ups (may be null or empty)
     * @return          new Recurring_Donation__c Ids in request order
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {

        // ---- guard: null / empty list ----
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        // ---- Phase 1: validate ALL requests before any DML ----
        for (GiftRequest req : requests) {
            if (req.contactId == null) {
                throw new RecurringGiftException(
                    'Contact ID is required for every gift request.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException(
                    'Amount must be a positive number.');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                throw new RecurringGiftException(
                    'Day of month must be between 1 and 31.');
            }
            if (req.startDate == null) {
                throw new RecurringGiftException(
                    'Start date is required.');
            }
        }

        // ---- Phase 2: build records (no DML yet) ----
        List<npe03__Recurring_Donation__c> rdRecords =
            new List<npe03__Recurring_Donation__c>(requests.size());

        for (GiftRequest req : requests) {

            npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c();

            // Donor
            rd.npe03__Contact__c = req.contactId;

            // Amount per installment
            rd.npe03__Amount__c = req.amount;

            // Schedule: monthly, every 1 period
            rd.npe03__Installment_Period__c   = 'Month';
            rd.npsp__InstallmentFrequency__c  = 1;

            // Day-of-month / last-day handling
            // npsp__Day_of_Month__c is a Text field
            if (req.dayOfMonth == 31) {
                // "31" from the form means "last day of the month"
                rd.npsp__Always_Use_Last_Day_Of_Month__c = true;
                rd.npsp__Day_of_Month__c = '31';
            } else {
                // 1-30 stored as that day number
                rd.npsp__Day_of_Month__c = String.valueOf(req.dayOfMonth);
            }

            // Dates
            rd.npsp__StartDate__c         = req.startDate;
            rd.npe03__Date_Established__c = Date.today();

            // Recurring type (Enhanced RD)
            rd.npsp__RecurringType__c = 'Recurring';

            // Fixed vs open-ended
            if (req.installments == null || req.installments == 0) {
                // Open-ended – no planned end
                rd.npe03__Open_Ended_Status__c = 'Open';
            } else {
                // Fixed number of installments
                rd.npe03__Installments__c      = req.installments;
                rd.npe03__Open_Ended_Status__c = 'Closed';
            }

            // Status
            rd.npsp__Status__c = 'Active';

            // Payment method
            rd.npsp__PaymentMethod__c = req.paymentMethod;

            rdRecords.add(rd);
        }

        // ---- Phase 3: single bulk DML ----
        insert rdRecords;

        // ---- Phase 4: return Ids in request order ----
        List<Id> result = new List<Id>(rdRecords.size());
        for (npe03__Recurring_Donation__c rd : rdRecords) {
            result.add(rd.Id);
        }
        return result;
    }
}
