            SELECT Id, FirstName, LastName, npe01__Contacts_Account__c
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist.');
        }

        Contact donor = contacts[0];
        Id householdId = donor.npe01__Contacts_Account__c;

        // --- Retrieve every contact in the same household ---
        List<Contact> householdMembers = [
            SELECT Id
            FROM Contact
            WHERE npe01__Contacts_Account__c = :householdId
        ];

        // --- Build Opportunity name (yyyy-MM-dd via String.valueOf on Date) ---
        String oppName = donor.FirstName + ' ' + donor.LastName + ' Donation '
                       + String.valueOf(giftDate);

        // --- Create the Opportunity (Closed Won) ---
        Opportunity opp = new Opportunity(
            Name                      = oppName,
            AccountId                 = householdId,
            StageName                 = 'Closed Won',
            Amount                    = amount,
            CloseDate                 = giftDate,
            npsp__Primary_Contact__c  = contactId
        );
        insert opp;

        // --- Build Contact Roles (exactly one role per contact) ---
        List<OpportunityContactRole> roles = new List<OpportunityContactRole>();

        // Donor role for the gifting contact
        roles.add(new OpportunityContactRole(
            ContactId     = contactId,
            OpportunityId = opp.Id,
            Role          = 'Donor'
        ));

        // Household Member role for every other household member
        for (Contact c : householdMembers) {
            if (c.Id != contactId) {
                roles.add(new OpportunityContactRole(
                    ContactId     = c.Id,
                    OpportunityId = opp.Id,
                    Role          = 'Household Member'
                ));
