```java
/**
 * Service to create NPSP Parent/Child relationship pairs.
 *
 * For each (child → parent) pair supplied, ONE npe4__Relationship__c record
 * is inserted (child → parent, Type = 'Parent').  NPSP's "List Setting"
 * reciprocal method auto-creates the reverse record (parent → child) using
 * the Relationship Lookup configuration.
 *
 * Bulk-safe: at most 1 SOQL and 1 DML regardless of map size.
 */
public class FamilyService {

    public static void linkParents(Map<Id, Id> parentIdByChildId) {

        // ── guard ──────────────────────────────────────────────────────────────
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // ── collect & validate IDs ─────────────────────────────────────────────
        Set<Id> allContactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            allContactIds.add(childId);
            allContactIds.add(parentId);
        }

        if (allContactIds.isEmpty()) {
            return;
        }

        // ── SOQL 1 (the only query) – existing relationships among the set ─────
        //    Any relationship in EITHER direction causes the pair to be skipped,
        //    making the import idempotent / re-runnable.
        Set<String> existingPairKeys = new Set<String>();

        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM   npe4__Relationship__c
            WHERE  npe4__Contact__c        IN :allContactIds
              AND  npe4__RelatedContact__c IN :allContactIds
        ]) {
            // Store both directional keys so lookups are O(1)
            existingPairKeys.add(
                String.valueOf(rel.npe4__Contact__c) + ',' +
                String.valueOf(rel.npe4__RelatedContact__c)
            );
        }

        // ── build new records (1 per pair – NPSP auto-creates the reciprocal) ──
        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        // Track pairs already handled within THIS batch to avoid intra-batch dupes
        Set<String> batchPairKeys = new Set<String>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (parentId == null || childId == parentId) {
                continue;
            }

            String childToParent = String.valueOf(childId)  + ',' + String.valueOf(parentId);
            String parentToChild = String.valueOf(parentId) + ',' + String.valueOf(childId);

            // Skip if a relationship already exists in the DB (either direction)
            if (existingPairKeys.contains(childToParent) ||
                existingPairKeys.contains(parentToChild)) {
                continue;
            }

            // Skip if already handled within this same batch (e.g. A→B and B→A)
            if (batchPairKeys.contains(childToParent) ||
                batchPairKeys.contains(parentToChild)) {
                continue;
            }

            batchPairKeys.add(childToParent);
            batchPairKeys.add(parentToChild);

            // Insert only the child → parent record.
            // NPSP's "List Setting" reciprocal method will auto-create the
            // parent → child record with the correct reciprocal Type (Son /
            // Daughter / Child) based on the npe4__Relationship_Lookup__c
            // configuration for "Parent".
            toInsert.add(new npe4__Relationship__c(
